// DECOMP-BN: sub_003BA7D8 (0x003BA7D8 - 0x003BA898, 47 insns, leaf)
// DmaRefDesc { uint32_t addr; uint16_t qwc; uint16_t pad; uint32_t unk08; int32_t mode; }
// Writes a 128-bit DMA REF tag + VIF1 header for VU1 data upload:
//   - If desc->addr (0x0) == 0: returns pkt ($a1) unchanged.
//   - If desc->mode (0xC) == 0: writes 1 QW:
//       word0 = 0x30000000 | desc->qwc           (DMA REF tag: ID=3 REF, QWC=[15:0])
//       word1 = desc->addr & 0x0FFFFFFF          (DMA REF source address)
//       word2 = 0x01000101                       (VIF STCYCL CL=1, WL=1)
//       word3 = 0x6C000000 | (flags ? 0x8000 : 0) | (desc->qwc << 16) | vuAddr
//               (VIF UNPACK V4-32: cmd=0x6C, FLG bit 15, num=[23:16], addr=[9:0])
//     returns pkt + 0x10.
//   - If desc->mode (0xC) == 1: writes 1 QW:
//       word0 = 0x30000000 | desc->qwc           (DMA REF tag: ID=3 REF, QWC=[15:0])
//       word1 = desc->addr & 0x0FFFFFFF          (DMA REF source address)
//       word2 = 0x01000101                       (VIF STCYCL CL=1, WL=1)
//       word3 = 0x00000000                       (VIF NOP)
//     returns pkt + 0x10.
//   - Otherwise: returns pkt ($a1) unchanged.
void sub_003BA7D8_decomp(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime) // DECOMP-BN
{
    const uint32_t desc = GPR_U32(ctx, 4);            // $a0: DmaRefDesc*
    const uint32_t pkt = GPR_U32(ctx, 5);             // $a1: packet write ptr
    const uint32_t vuAddr = GPR_U32(ctx, 6);          // $a2: VU1 destination addr
    const uint64_t flags = GPR_U64(ctx, 7) & 0xFFull; // $a3: UNPACK FLG enable

    const uint32_t dataAddr = READ32(desc);
    if (dataAddr == 0u)
    {
        SET_GPR_U64(ctx, 2, GPR_U64(ctx, 5)); // $v0 = pkt
        ctx->pc = GPR_U32(ctx, 31);
        return;
    }

    const int32_t mode = static_cast<int32_t>(READ32(desc + 12u));
    if (mode != 0 && mode != 1)
    {
        SET_GPR_U64(ctx, 2, GPR_U64(ctx, 5)); // $v0 = pkt
        ctx->pc = GPR_U32(ctx, 31);
        return;
    }

    const uint32_t addr28 = dataAddr & 0x0FFFFFFFu;
    const uint16_t qwc = READ16(desc + 4u);
    const uint64_t qwLo = (static_cast<uint64_t>(addr28) << 32) | 0x30000000ull | qwc;
    uint64_t qwHi = 0x01000101ull;
    if (mode == 0)
    {
        const uint32_t unpackBase = (flags != 0) ? 0x6C008000u : 0x6C000000u;
        const uint32_t unpackCode = unpackBase | vuAddr | (static_cast<uint32_t>(qwc) << 16);
        qwHi |= static_cast<uint64_t>(unpackCode) << 32;
    }

    WRITE64(pkt, qwLo);
    WRITE64(pkt + 8u, qwHi);

    SET_GPR_S32(ctx, 2, static_cast<int32_t>(pkt + 16u)); // $v0 = pkt + 16
    ctx->pc = GPR_U32(ctx, 31);
}

// DECOMP-BN: sub_003B5890 (0x003B5890 - 0x003B5900, 27 insns, leaf)
// Emits pairs of 128-bit DMA CALL tags (0x50000000 = ID 5 CALL) for each
// non-(-1) entry in `indices[0..count-1]`:
//   QW 0: word0 = 0x50000000, word1 = sizes[i], word2 = 0, word3 = 0
//   QW 1: word0 = 0x50000000, word1 = table[indices[i]], word2 = 0, word3 = 0
// Returns updated packet pointer ($v0).
void sub_003B5890_decomp(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime) // DECOMP-BN
{
    uint32_t out = GPR_U32(ctx, 4);           // $a0 -> $v0: packet write ptr
    const uint32_t indices = GPR_U32(ctx, 5); // $a1: int8_t index array
    uint32_t sizes = GPR_U32(ctx, 6);         // $a2: uint32_t array
    const uint32_t table = GPR_U32(ctx, 7);   // $a3: uint32_t lookup table
    const uint64_t count = GPR_U64(ctx, 8);   // $t0: element count

    if (count == 0)
    {
        SET_GPR_U64(ctx, 2, GPR_U64(ctx, 4)); // $v0 = out
        ctx->pc = GPR_U32(ctx, 31);
        return;
    }

    uint32_t idx = 0;
    do
    {
        const int8_t entry = static_cast<int8_t>(READ8(indices + idx));
        idx += 1u;

        if (entry != -1)
        {
            const uint32_t sz = READ32(sizes);
            const uint64_t qw0 = (static_cast<uint64_t>(sz) << 32) | 0x50000000ull;
            WRITE64(out + 8u, 0ull);
            WRITE64(out, qw0);
            out += 16u;

            const uint32_t tableAddr = table + static_cast<uint32_t>(static_cast<int32_t>(entry) << 2);
            const uint32_t tableVal = READ32(tableAddr);
            const uint64_t qw1 = (static_cast<uint64_t>(tableVal) << 32) | 0x50000000ull;
            WRITE64(out + 8u, 0ull);
            WRITE64(out, qw1);
            out += 16u;
        }

        sizes += 4u;
    } while (static_cast<uint64_t>(idx) < count);

    SET_GPR_S32(ctx, 2, static_cast<int32_t>(out));
    ctx->pc = GPR_U32(ctx, 31);
}

// DECOMP-BO: sub_003AFDD8 (0x003AFDD8 - 0x003AFE00, 10 insns, tail-calls 0x3AFD98)
// Prepares a DMA CALL + VIF FLUSH packet header and tail-calls sub_003AFD98:
//   - $a0 = pkt, $a1 = qwc & 0xFFFF, $a2 = mode/tag byte & 0xFF, $a3 = arg3
//   - $t0 = 0x11000000 (VIF FLUSH: cmd=0x11)
//   - $t1 = 0x50000000 | (qwc & 0xFFFF) (DMA CALL tag: ID=5 CALL, QWC=[15:0])
void sub_003AFDD8_decomp(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime) // DECOMP-BO
{
    const uint32_t sp = GPR_U32(ctx, 29) - 16u;
    WRITE64(sp, GPR_U64(ctx, 31)); // preserve stack write for dual-run equivalence

    const uint32_t qwc = GPR_U32(ctx, 5) & 0xFFFFu;
    SET_GPR_U64(ctx, 5, static_cast<uint64_t>(qwc));
    SET_GPR_U64(ctx, 6, GPR_U64(ctx, 6) & 0xFFull);
    SET_GPR_S32(ctx, 8, 0x11000000);
    SET_GPR_U64(ctx, 9, static_cast<uint64_t>(qwc) | 0x50000000ull);
    SET_GPR_U64(ctx, 31, READ64(sp));

    ctx->pc = 0x3AFD98u;
    if (PS2Runtime::RecompiledFunction fn = runtime->lookupFunction(0x3AFD98u))
    {
        fn(rdram, ctx, runtime);
    }
}

// DECOMP-BO: sub_003AFE58 (0x003AFE58 - 0x003AFEA8, 20 insns, calls 0x3AFDD8)
// Emits a single-register GS A+D GIF packet (2 QWs after 1-QW DMA/VIF header):
//   - Calls sub_003AFDD8(pkt, qwc=2, 0x10, 0) -> DMA CALL(qwc=2) + VIF FLUSH
//   - QW +0x10: GIFtag (NLOOP=1, EOP=1 [bit 15], NREG=1 [bits 63:60], FLG=PACKED, REGS=0xE A+D)
//   - QW +0x20: GS A+D payload (data=$a2, reg=$a1)
// Returns updated packet pointer ($v0 + 0x20).
void sub_003AFE58_decomp(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime) // DECOMP-BO
{
    const uint32_t pkt = GPR_U32(ctx, 4);    // $a0: packet write ptr
    const uint64_t gsReg = GPR_U64(ctx, 5);  // $a1: GS register address
    const uint64_t gsData = GPR_U64(ctx, 6); // $a2: GS register data

    WRITE64(pkt + 0x10u, 0x1000000000008001ull); // GIFtag: NLOOP=1, EOP=1, NREG=1
    WRITE64(pkt + 0x18u, 0xEull);                // GIFtag: REGS[0] = 0xE (A+D)
    WRITE64(pkt + 0x20u, gsData);
    WRITE64(pkt + 0x28u, gsReg);

    const uint32_t sp = GPR_U32(ctx, 29) - 16u;
    SET_GPR_S32(ctx, 29, static_cast<int32_t>(sp));
    WRITE64(sp, GPR_U64(ctx, 31));

    SET_GPR_S32(ctx, 5, 2);
    SET_GPR_S32(ctx, 6, 0x10);
    SET_GPR_U64(ctx, 7, 0ull);
    SET_GPR_U32(ctx, 31, 0x3AFE94u);
    ctx->pc = 0x3AFDD8u;
    if (!PS2_DCALL(0x3AFDD8u, 0x3AFE94u))
    {
        return;
    }

    SET_GPR_U64(ctx, 31, READ64(sp));
    SET_GPR_S32(ctx, 2, static_cast<int32_t>(GPR_U32(ctx, 2) + 0x20u));
    SET_GPR_S32(ctx, 29, static_cast<int32_t>(sp + 16u));
    ctx->pc = GPR_U32(ctx, 31);
}

// DECOMP-BO: Shared helper for sub_003AFEA8 / sub_003AFED8.
// Reads obj = *(state + ptrOffset); if non-null, emits 1-QW DMA CALL tag:
//   word0 = 0x50000000 (DMA CALL, QWC=0), word1 = *(obj + tagOffset), word2..3 = 0
// Returns pkt + 0x10 if emitted, else pkt unchanged.
void emitObjDmaCallTag(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime, uint32_t ptrOffset,uint32_t tagOffset) // DECOMP-BO
{
    const uint32_t pkt = GPR_U32(ctx, 4);
    const uint32_t state = GPR_U32(ctx, 5);
    const uint32_t obj = READ32(state + ptrOffset);
    if (obj == 0u)
    {
        SET_GPR_U64(ctx, 2, GPR_U64(ctx, 4));
        ctx->pc = GPR_U32(ctx, 31);
        return;
    }

    const uint32_t callAddr = READ32(obj + tagOffset);
    WRITE64(pkt + 8u, 0ull);
    WRITE64(pkt, (static_cast<uint64_t>(callAddr) << 32) | 0x50000000ull);
    SET_GPR_S32(ctx, 2, static_cast<int32_t>(pkt + 16u));
    ctx->pc = GPR_U32(ctx, 31);
}

