void sub_003B4290_decomp(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime) // DECOMP-BO
{
    (void)runtime;
    WRITE32(0x1000E010u, 0x100u);
    WRITE32(0x1000D020u, GPR_U32(ctx, 6));
    WRITE32(0x1000D080u, GPR_U32(ctx, 5));
    WRITE32(0x1000D010u, GPR_U32(ctx, 4));
    WRITE32(0x1000D000u, 0x100u);
    ctx->pc = GPR_U32(ctx, 31);
}

