// DrawCmd   { +0x10 u32 slotIdx; +0x14 u32 callTarget; +0x18 u32 nextAddr; +0x1C u32 nextPatchPtr; }
// Patches DMA NEXT (0x20000000) / CALL (0x50000000) tags when slot's cachedTarget changes. Returns 0.
void sub_003B9158_decomp(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime) // DECOMP-BR
{
    const uint32_t sp = GPR_U32(ctx, 29) - 0x30u;
    SET_GPR_S32(ctx, 29, static_cast<int32_t>(sp));
    WRITE64(sp + 0u, GPR_U64(ctx, 16));
    WRITE64(sp + 8u, GPR_U64(ctx, 17));
    WRITE64(sp + 16u, GPR_U64(ctx, 18));
    WRITE64(sp + 24u, GPR_U64(ctx, 19));
    WRITE64(sp + 32u, GPR_U64(ctx, 20));
    WRITE64(sp + 40u, GPR_U64(ctx, 31));

    const uint32_t rctx = GPR_U32(ctx, 4);
    const uint32_t cmd = GPR_U32(ctx, 5);
    const uint32_t stateCache = rctx + 0x70D8u;

    SET_GPR_S32(ctx, 18, static_cast<int32_t>(cmd));
    SET_GPR_S32(ctx, 19, static_cast<int32_t>(stateCache));
    SET_GPR_S32(ctx, 20, static_cast<int32_t>(rctx));

    const uint32_t slot = READ32(cmd + 0x10u);
    const uint32_t target = READ32(cmd + 0x14u);
    const uint32_t slotPtr = stateCache + (slot << 2);
    uint32_t patchPtr = READ32(stateCache + 4u);

    SET_GPR_S32(ctx, 16, static_cast<int32_t>(target));
    SET_GPR_S32(ctx, 17, static_cast<int32_t>(patchPtr));

    if (target != READ32(slotPtr + 8u))
    {
        WRITE32(slotPtr + 8u, target);
        SET_GPR_S32(ctx, 4, static_cast<int32_t>(rctx));
        SET_GPR_U32(ctx, 31, 0x3B91A4u);
        ctx->pc = 0x3B3D80u;
        if (!PS2_DCALL(0x3B3D80u, 0x3B91A4u))
        {
            return;
        }
        const uint32_t pktPtr = GPR_U32(ctx, 2);
        const uint64_t nextToPkt = 0x20000000ull | (static_cast<uint64_t>(pktPtr & 0x0FFFFFFFu) << 32);
        WRITE64(patchPtr + 0u, nextToPkt);
        WRITE64(patchPtr + 8u, 0ull);

        const uint64_t callTag = 0x50000000ull | (static_cast<uint64_t>(target) << 32);
        WRITE64(pktPtr + 0u, callTag);
        WRITE64(pktPtr + 8u, 0ull);

        const uint32_t nextAddr = READ32(cmd + 0x18u) & 0x0FFFFFFFu;
        const uint64_t nextTag = 0x20000000ull | (static_cast<uint64_t>(nextAddr) << 32);
        WRITE64(pktPtr + 0x10u, nextTag);
        WRITE64(pktPtr + 0x18u, 0ull);

        patchPtr = READ32(cmd + 0x1Cu);
        SET_GPR_S32(ctx, 17, static_cast<int32_t>(patchPtr));
        SET_GPR_S32(ctx, 4, static_cast<int32_t>(rctx));
        SET_GPR_S32(ctx, 5, static_cast<int32_t>(pktPtr + 0x20u));
        SET_GPR_U32(ctx, 31, 0x3B9204u);
        ctx->pc = 0x3B3D88u;
        if (!PS2_DCALL(0x3B3D88u, 0x3B9204u))
        {
            return;
        }
    }
    else
    {
        const uint32_t nextAddr = READ32(cmd + 0x18u) & 0x0FFFFFFFu;
        const uint64_t nextTag = 0x20000000ull | (static_cast<uint64_t>(nextAddr) << 32);
        WRITE64(patchPtr + 0u, nextTag);
        WRITE64(patchPtr + 8u, 0ull);
        patchPtr = READ32(cmd + 0x1Cu);
        SET_GPR_S32(ctx, 17, static_cast<int32_t>(patchPtr));
    }

    WRITE32(stateCache + 4u, patchPtr);
    SET_GPR_U64(ctx, 2, 0ull);
    SET_GPR_U64(ctx, 16, READ64(sp + 0u));
    SET_GPR_U64(ctx, 17, READ64(sp + 8u));
    SET_GPR_U64(ctx, 18, READ64(sp + 16u));
    SET_GPR_U64(ctx, 19, READ64(sp + 24u));
    SET_GPR_U64(ctx, 20, READ64(sp + 32u));
    SET_GPR_U64(ctx, 31, READ64(sp + 40u));
    SET_GPR_S32(ctx, 29, static_cast<int32_t>(sp + 0x30u));
    ctx->pc = GPR_U32(ctx, 31);
}

// DECOMP-BR: sub_003BD538 (0x003BD538 - 0x003BD5D0, 39 insns at entry, leaf, VU0; file also has trailing secondary entry)
// name: mat4InvertAffine
// Inverts 4x4 affine matrix *a1 into *a0 using VU0 cofactors + vdiv; preserves exact VU0 register state.
void sub_003BD538_decomp(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime) // DECOMP-BR
{
    const uint32_t dst = GPR_U32(ctx, 4);
    const uint32_t src = GPR_U32(ctx, 5);

    __m128 vf1 = _mm_castsi128_ps(READ128(src + 0u));
    __m128 vf2 = _mm_castsi128_ps(READ128(src + 16u));
    __m128 vf3 = _mm_castsi128_ps(READ128(src + 32u));
    __m128 vf4 = _mm_castsi128_ps(READ128(src + 48u));

    const __m128i xyzMask = _mm_set_epi32(0, -1, -1, -1);
    const __m128i wMask = _mm_set_epi32(-1, 0, 0, 0);
    const __m128i xMask = _mm_set_epi32(0, 0, 0, -1);
    const __m128i yMask = _mm_set_epi32(0, 0, -1, 0);
    const __m128i zMask = _mm_set_epi32(0, -1, 0, 0);

    auto crossXyz = [&](__m128 a, __m128 b, __m128 dstOld, __m128 &acc) -> __m128 {
        __m128 a_yzx = _mm_shuffle_ps(a, a, _MM_SHUFFLE(3, 0, 2, 1));
        __m128 b_zxy = _mm_shuffle_ps(b, b, _MM_SHUFFLE(3, 1, 0, 2));
        acc = _mm_blendv_ps(acc, PS2_VMUL(a_yzx, b_zxy), _mm_castsi128_ps(xyzMask));

        __m128 b_yzx = _mm_shuffle_ps(b, b, _MM_SHUFFLE(3, 0, 2, 1));
        __m128 a_zxy = _mm_shuffle_ps(a, a, _MM_SHUFFLE(3, 1, 0, 2));
        __m128 sub = PS2_VSUB(acc, PS2_VMUL(b_yzx, a_zxy));
        return _mm_blendv_ps(dstOld, sub, _mm_castsi128_ps(xyzMask));
    };

    __m128 acc = ctx->vu0_acc;
    __m128 vf7 = crossXyz(vf1, vf2, ctx->vu0_vf[7], acc);
    const __m128 vf11 = _mm_blendv_ps(
        ctx->vu0_vf[11],
        PS2_VADD(ctx->vu0_vf[0], _mm_shuffle_ps(ctx->vu0_vf[0], ctx->vu0_vf[0], _MM_SHUFFLE(3, 3, 3, 3))),
        _mm_castsi128_ps(xyzMask));
    __m128 vf5 = crossXyz(vf2, vf3, ctx->vu0_vf[5], acc);
    __m128 vf8 = PS2_VMUL(vf7, vf3);
    __m128 vf6 = crossXyz(vf3, vf1, ctx->vu0_vf[6], acc);

    vf4 = PS2_VBLEND(vf4, PS2_VSUB(ctx->vu0_vf[0], vf4), _mm_castsi128_ps(xyzMask));
    acc = _mm_blendv_ps(acc, PS2_VADD(vf8, _mm_shuffle_ps(vf8, vf8, _MM_SHUFFLE(1, 1, 1, 1))), _mm_castsi128_ps(xMask));
    vf8 = _mm_blendv_ps(
        vf8,
        PS2_VADD(acc, PS2_VMUL(vf11, _mm_shuffle_ps(vf8, vf8, _MM_SHUFFLE(2, 2, 2, 2)))),
        _mm_castsi128_ps(xMask));

    const float det = _mm_cvtss_f32(vf8);
    const float vf0w = _mm_cvtss_f32(_mm_shuffle_ps(ctx->vu0_vf[0], ctx->vu0_vf[0], _MM_SHUFFLE(0, 0, 0, 3)));
    ctx->vu0_q = ps2x_vu0_div(vf0w, det);
    vf4 = _mm_blendv_ps(vf4, ctx->vu0_vf[0], _mm_castsi128_ps(wMask));

    const __m128 vf10 = _mm_blendv_ps(
        ctx->vu0_vf[10],
        PS2_VADD(ctx->vu0_vf[0], _mm_set1_ps(ctx->vu0_q)),
        _mm_castsi128_ps(xyzMask));

    const __m128 zeroW = PS2_VSUB(ctx->vu0_vf[0], ctx->vu0_vf[0]);
    vf1 = PS2_VBLEND(vf1, zeroW, _mm_castsi128_ps(wMask));
    vf2 = PS2_VBLEND(vf2, zeroW, _mm_castsi128_ps(wMask));
    vf3 = PS2_VBLEND(vf3, zeroW, _mm_castsi128_ps(wMask));

    auto setCol = [&](__m128 col, int laneMaskIdx) {
        const __m128i mask = (laneMaskIdx == 0) ? xMask : (laneMaskIdx == 1 ? yMask : zMask);
        vf1 = _mm_blendv_ps(vf1, PS2_VMUL(vf10, _mm_shuffle_ps(col, col, _MM_SHUFFLE(0, 0, 0, 0))), _mm_castsi128_ps(mask));
        vf2 = _mm_blendv_ps(vf2, PS2_VMUL(vf10, _mm_shuffle_ps(col, col, _MM_SHUFFLE(1, 1, 1, 1))), _mm_castsi128_ps(mask));
        vf3 = _mm_blendv_ps(vf3, PS2_VMUL(vf10, _mm_shuffle_ps(col, col, _MM_SHUFFLE(2, 2, 2, 2))), _mm_castsi128_ps(mask));
    };
    setCol(vf5, 0);
    setCol(vf6, 1);
    setCol(vf7, 2);

    acc = _mm_blendv_ps(acc, PS2_VMUL(vf1, _mm_shuffle_ps(vf4, vf4, _MM_SHUFFLE(0, 0, 0, 0))), _mm_castsi128_ps(xyzMask));
    acc = _mm_blendv_ps(acc, PS2_VADD(acc, PS2_VMUL(vf2, _mm_shuffle_ps(vf4, vf4, _MM_SHUFFLE(1, 1, 1, 1)))), _mm_castsi128_ps(xyzMask));
    vf4 = _mm_blendv_ps(vf4, PS2_VADD(acc, PS2_VMUL(vf3, _mm_shuffle_ps(vf4, vf4, _MM_SHUFFLE(2, 2, 2, 2)))), _mm_castsi128_ps(xyzMask));

    ctx->vu0_vf[1] = vf1;
    ctx->vu0_vf[2] = vf2;
    ctx->vu0_vf[3] = vf3;
    ctx->vu0_vf[4] = vf4;
    ctx->vu0_vf[5] = vf5;
    ctx->vu0_vf[6] = vf6;
    ctx->vu0_vf[7] = vf7;
    ctx->vu0_vf[8] = vf8;
    ctx->vu0_vf[10] = vf10;
    ctx->vu0_vf[11] = vf11;
    ctx->vu0_acc = acc;

    WRITE128(dst + 0u, _mm_castps_si128(vf1));
    WRITE128(dst + 16u, _mm_castps_si128(vf2));
    WRITE128(dst + 32u, _mm_castps_si128(vf3));
    WRITE128(dst + 48u, _mm_castps_si128(vf4));
    ctx->pc = GPR_U32(ctx, 31);
}

// DECOMP-BR: sub_003BD690 (0x003BD690 - 0x003BD6D0, 17 insns at entry, leaf, VU0; file also has trailing secondary entry)
// name: mat4MulVu0
// Multiplies 4x4 matrices *a1 and *a2 via VU0 microprogram 0x0, stores result ($vf8..$vf11) into *a0,
// and returns $vf3 in $v0.
void sub_003BD690_decomp(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime) // DECOMP-BR
{
    const uint32_t dst = GPR_U32(ctx, 4);
    const uint32_t m0 = GPR_U32(ctx, 5);
    const uint32_t m1 = GPR_U32(ctx, 6);

    ctx->vu0_vf[4] = _mm_castsi128_ps(READ128(m0 + 0u));
    ctx->vu0_vf[5] = _mm_castsi128_ps(READ128(m0 + 16u));
    ctx->vu0_vf[6] = _mm_castsi128_ps(READ128(m0 + 32u));
    ctx->vu0_vf[7] = _mm_castsi128_ps(READ128(m0 + 48u));
    ctx->vu0_vf[8] = _mm_castsi128_ps(READ128(m1 + 0u));
    ctx->vu0_vf[9] = _mm_castsi128_ps(READ128(m1 + 16u));
    ctx->vu0_vf[10] = _mm_castsi128_ps(READ128(m1 + 32u));
    ctx->vu0_vf[11] = _mm_castsi128_ps(READ128(m1 + 48u));

    ctx->vu0_tpc = 0x0u;
    runtime->executeVU0Microprogram(rdram, ctx, 0x0u);

    SET_GPR_VEC(ctx, 2, _mm_castps_si128(ctx->vu0_vf[3]));
    WRITE128(dst + 0u, _mm_castps_si128(ctx->vu0_vf[8]));
    WRITE128(dst + 16u, _mm_castps_si128(ctx->vu0_vf[9]));
    WRITE128(dst + 32u, _mm_castps_si128(ctx->vu0_vf[10]));
    WRITE128(dst + 48u, _mm_castps_si128(ctx->vu0_vf[11]));
    ctx->pc = GPR_U32(ctx, 31);
}

