    SET_GPR_U64(ctx, 16, GPR_U64(ctx, 4));
    SET_GPR_U64(ctx, 17, GPR_U64(ctx, 5));

    SET_GPR_U64(ctx, 4, GPR_U64(ctx, 5));
    SET_GPR_U32(ctx, 31, 0x3B7EE0u);
    ctx->pc = 0x3AF9C8u;
