    const uint32_t renderCtx = GPR_U32(ctx, 16);
    const uint32_t node = GPR_U32(ctx, 17);
    const uint32_t idx = READ32(renderCtx + 0x70A0u);
    WRITE32(renderCtx + 0x70A0u, idx + 1u);
    WRITE32(renderCtx + 0x689Cu + (idx << 2), node);

