    ctx->vu0_vf[4] = _mm_castsi128_ps(READ128(mat0 + 0u));
    ctx->vu0_vf[5] = _mm_castsi128_ps(READ128(mat0 + 16u));
    ctx->vu0_vf[6] = _mm_castsi128_ps(READ128(mat0 + 32u));
    ctx->vu0_vf[7] = _mm_castsi128_ps(READ128(mat0 + 48u));

