        SET_GPR_S32(ctx, 16, static_cast<int32_t>(diffAddr));
        SET_GPR_S32(ctx, 4, static_cast<int32_t>(diffAddr));
        SET_GPR_S32(ctx, 5, static_cast<int32_t>(fsp));
