    const __m128 vf6z = _mm_shuffle_ps(vf6, vf6, _MM_SHUFFLE(2, 2, 2, 2));
    const __m128 vf7y = _mm_shuffle_ps(vf7, vf7, _MM_SHUFFLE(1, 1, 1, 1));
    const __m128 vf7z = _mm_shuffle_ps(vf7, vf7, _MM_SHUFFLE(2, 2, 2, 2));
    const __m128 vf8z = _mm_shuffle_ps(vf8, vf8, _MM_SHUFFLE(2, 2, 2, 2));
    const __m128 vf9x = _mm_shuffle_ps(vf9, vf9, _MM_SHUFFLE(0, 0, 0, 0));
    const __m128 vf9y = _mm_shuffle_ps(vf9, vf9, _MM_SHUFFLE(1, 1, 1, 1));
