    vf11 = _mm_blendv_ps(vf11, PS2_VSUB(acc, PS2_VMUL(vf1, vf9z)), _mm_castsi128_ps(maskX));
    vf11 = _mm_blendv_ps(vf11, PS2_VADD(vf7, vf9x), _mm_castsi128_ps(maskZ));
    vf11 = _mm_blendv_ps(vf11, PS2_VSUB(vf0, vf0w), _mm_castsi128_ps(maskW));
    ctx->vu0_vf[11] = vf11;

