    __m128 vf12 = _mm_blendv_ps(ctx->vu0_vf[12], PS2_VADD(acc, PS2_VMUL(vf1, vf9y)), _mm_castsi128_ps(maskX));
    acc = _mm_blendv_ps(acc, PS2_VADD(vf0, vf7z), _mm_castsi128_ps(maskY));
    vf12 = _mm_blendv_ps(vf12, PS2_VSUB(acc, PS2_VMUL(vf1, vf9x)), _mm_castsi128_ps(maskY));
    acc = _mm_blendv_ps(acc, PS2_VADD(vf0, vf0w), _mm_castsi128_ps(maskZ));
    acc = _mm_blendv_ps(acc, PS2_VSUB(acc, PS2_VMUL(vf1, vf6x)), _mm_castsi128_ps(maskZ));
    vf12 = _mm_blendv_ps(vf12, PS2_VSUB(acc, PS2_VMUL(vf1, vf7y)), _mm_castsi128_ps(maskZ));
    vf12 = _mm_blendv_ps(vf12, PS2_VSUB(vf0, vf0w), _mm_castsi128_ps(maskW));
