// DECOMP-BU: Helper for sub_003BBB50 - compute 32-bit material state cache hash.
static uint32_t computeMatStateHash(uint32_t k82c, uint32_t k830, uint32_t k834, uint32_t matDesc, uint16_t subKey) // DECOMP-BU
{
    uint32_t h = (k82c + matDesc) + (k830 + k834) + static_cast<uint32_t>(subKey);
    h += (h >> 16);
    h += (h >> 8);
    return h;
}

// DECOMP-BU: Helper for sub_003BBB50 - walk circular bucket list for matching MatStateEntry.
static uint32_t findMatchingMatState(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime, uint32_t head, /*DECOMP-BU2*/ uint32_t hash,
                                     uint32_t k82c, uint32_t k830, uint32_t k834,
                                     uint32_t matDesc, uint32_t subKey) // DECOMP-BU
{
    uint32_t node = head;
    do
    {
        if (READ32(node + 0x00u) == hash &&
            READ32(node + 0x30u) == matDesc &&
            READ32(node + 0x34u) == subKey &&
            READ32(node + 0x24u) == k82c &&
            READ32(node + 0x2Cu) == k830 &&
            READ32(node + 0x28u) == k834)
        {
            return node;
        }
        node = READ32(node + 0x04u);
    } while (node != head);
    return 0u;
}

