    WRITE64(lsp + 0x60u, GPR_U64(ctx, 22)); // $s6
    WRITE64(lsp + 0x68u, GPR_U64(ctx, 23)); // $s7
    WRITE64(lsp + 0x70u, GPR_U64(ctx, 30)); // $fp
    WRITE64(lsp + 0x78u, GPR_U64(ctx, 31)); // $ra

