// DECOMP-BU: Helper for sub_003B7A00 - compute 32-bit hash over RenderStateDesc + variable uint32 array.
static uint32_t computeRenderStateHash(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime, uint32_t w00, /*DECOMP-BU2*/ uint32_t arrPtr, uint32_t count,
                                       uint32_t w0C, uint32_t w10, uint32_t w14) // DECOMP-BU
{
    uint32_t h = (w00 + w10) + (w0C + count) + w14;
    for (uint32_t i = 0u; i < count; ++i)
    {
        h += READ32(arrPtr + (i << 2));
    }
    h += (h >> 16);
    h += (h >> 8);
    return h;
}

// DECOMP-BU: Helper for sub_003B7A00 - walk circular bucket list for matching RenderStateEntry.
static uint32_t findMatchingRenderState(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime, uint32_t head, /*DECOMP-BU2*/ uint32_t hash,
                                        uint32_t w00Bits, uint32_t arrPtr, uint32_t count,
                                        uint32_t w0C, uint32_t w10, uint32_t w14) // DECOMP-BU
{
    float targetF = 0.0f;
    std::memcpy(&targetF, &w00Bits, sizeof(targetF));

    uint32_t node = head;
    do
    {
        if (READ32(node + 0x00u) == hash)
        {
            const uint32_t nodeFBits = READ32(node + 0x20u);
            float nodeF = 0.0f;
            std::memcpy(&nodeF, &nodeFBits, sizeof(nodeF));
            if ((nodeF == targetF) &&
                READ32(node + 0x28u) == count &&
                READ32(node + 0x2Cu) == w0C &&
                READ32(node + 0x30u) == w10 &&
                READ32(node + 0x34u) == w14)
            {
                const uint32_t nodeArr = READ32(node + 0x24u);
                bool arrMatch = true;
                for (uint32_t i = 0u; i < count; ++i)
                {
                    if (READ32(nodeArr + (i << 2)) != READ32(arrPtr + (i << 2)))
                    {
                        arrMatch = false;
                        break;
                    }
                }
                if (arrMatch)
                {
                    return node;
                }
            }
        }
        node = READ32(node + 0x04u);
    } while (node != head);
    return 0u;
}

