    WRITE64(lsp + 0x00u, GPR_U64(ctx, 16)); // $s0
    WRITE64(lsp + 0x08u, GPR_U64(ctx, 17)); // $s1
    WRITE64(lsp + 0x10u, GPR_U64(ctx, 18)); // $s2
    WRITE64(lsp + 0x18u, GPR_U64(ctx, 19)); // $s3
    WRITE64(lsp + 0x20u, GPR_U64(ctx, 20)); // $s4
    WRITE64(lsp + 0x28u, GPR_U64(ctx, 21)); // $s5
    WRITE64(lsp + 0x30u, GPR_U64(ctx, 22)); // $s6
    WRITE64(lsp + 0x38u, GPR_U64(ctx, 31)); // $ra

    SET_GPR_U64(ctx, 20, GPR_U64(ctx, 4)); // $s4 = renderCtx
    SET_GPR_U64(ctx, 19, GPR_U64(ctx, 5)); // $s3 = stateDesc
    desc = GPR_U32(ctx, 5);
    w00 = READ32(desc + 0x00u);
    arrPtr = READ32(desc + 0x04u);
    count = READ32(desc + 0x08u);
    w0C = READ32(desc + 0x0Cu);
    w10 = READ32(desc + 0x10u);
    w14 = READ32(desc + 0x14u);

