// DECOMP-BV: Helper for sub_003ADEC0 - select neighbor tile source address for VU1 UNPACK.
static uint32_t selectTileNeighborAddr(uint32_t baseAddr, int32_t tileX, int32_t lastX,
                                       int32_t tileY, int32_t tilesY, uint32_t rowStride,
                                       int32_t selfOffset, int32_t prevOffset, int32_t nextOffset,
                                       bool isPrevEdge) // DECOMP-BV
{
    const uint32_t rowBase = (tileX == lastX) ? baseAddr : (baseAddr + rowStride);
    if (isPrevEdge)
    {
        return (tileY == 0) ? (rowBase + static_cast<uint32_t>(selfOffset))
                            : (rowBase + static_cast<uint32_t>(prevOffset));
    }
    return (tileY == tilesY - 1) ? (rowBase + static_cast<uint32_t>(selfOffset))
                                 : (rowBase + static_cast<uint32_t>(nextOffset));
}

