{
    const uint32_t raw = READ32(slotAddr);
    if (raw == 0xFFFFFFFFu)
    {
        WRITE32(slotAddr, 0u);
        return 0u;
    }
    if (raw == 0u)
    {
        return 0u;
    }
    const uint32_t relocated = raw + base;
    WRITE32(slotAddr, relocated);
    return relocated;
}

